function [zero_torque, step] = mfun_fvc_flying_start(enable, p)
%MFUN_FVC_FLYING_START Block FlyingStart of the control system.
%   FlyingStart of motulator. Generated by motulator_export from the MATLAB port of
%   motulator and called by the MATLAB Function block of the Simulink model, which adds
%   its folder to the MATLAB path. The parameters are the fields of the struct p (from
%   the mask, [] as NaN). The state is in persistent variables, of which each MATLAB
%   Function block has its own copy.
persistent self
if isempty(self)
    self = struct('step', 0);
end
% The step of the flying start of a sensorless drive
next = 0;
if p.sensorless > 0
    if enable <= 0
        next = 1;
    elseif self.step == 1
        next = 2;
    elseif self.step == 2
        next = 3;
    end
end
step = next;
zero_torque = double(enable <= 0 || next == 2);
self.step = next;
end
